static struct key_state * dco_get_secondary_key ( struct tls_multi * multi , const struct key_state * primary ) { for ( int i = 0 ; i < KEY_SCAN_SIZE ; ++ i ) { struct key_state * ks = get_key_scan ( multi , i ) ; struct key_ctx_bi * key = & ks -> crypto_options . key_ctx_bi ; if ( ks == primary ) { continue ; } if ( ks -> state >= S_GENERATED_KEYS && ks -> authenticated == KS_AUTH_TRUE ) { return ks ; } } return NULL ; } 